begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','public.application_packages','UPDATE'),'package snapshots cannot be rewritten');
select ok(not has_table_privilege('authenticated','public.application_packages','DELETE'),'package history cannot be individually erased');
select ok(not has_table_privilege('anon','public.resume_facts','SELECT'),'resume text is private');
select ok(not has_function_privilege('anon','public.record_application_package(uuid,uuid,uuid,timestamptz,timestamptz,timestamptz,timestamptz,jsonb,jsonb)','EXECUTE'),'anonymous package generation denied');
insert into auth.users(id,email) values('15000000-0000-0000-0000-000000000001','prep-one@example.test'),('15000000-0000-0000-0000-000000000002','prep-two@example.test');
insert into public.candidate_profiles(id,user_id,full_name,email) values('25000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000001','Preparation Fixture','prep-one@example.test');
insert into public.resumes(id,user_id,profile_id,role_category,version_name,storage_path) values('35000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000001','25000000-0000-0000-0000-000000000001','backend','Synthetic v1','15000000-0000-0000-0000-000000000001/prep.txt');
insert into public.jobs(id,user_id,source_platform,canonical_url,company_name,job_title,description) values('45000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000001','manual','https://example.test/prep','Synthetic employer','Backend','Synthetic listing only.');
insert into public.applications(id,user_id,job_id) values('55000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000001','45000000-0000-0000-0000-000000000001');
set local role authenticated;
set local request.jwt.claim.sub='15000000-0000-0000-0000-000000000001';
insert into public.resume_facts(resume_id,user_id,text_content) values('35000000-0000-0000-0000-000000000001',auth.uid(),'Synthetic factual resume text.');
select is((select verified_at from public.resume_facts),null::timestamptz,'extracted draft is unverified');
select throws_ok($$select public.record_application_package('55000000-0000-0000-0000-000000000001','35000000-0000-0000-0000-000000000001','65000000-0000-0000-0000-000000000001',(select updated_at from public.applications),(select updated_at from public.jobs),(select updated_at from public.candidate_profiles),(select updated_at from public.resume_facts),'[]','{"answers":[],"cover_letter":"Synthetic letter"}')$$,'23514',null,'unverified text cannot generate a package');
update public.resume_facts set verified_by_candidate=true;
select ok((select verified_at is not null from public.resume_facts),'candidate verification records a timestamp');
select throws_ok($$insert into public.answer_library(question_key,question_pattern,answer_text,category,requires_review,verified_by_candidate) values('sponsor','Do you need visa sponsorship?','Synthetic response','routine',false,true)$$,'23514',null,'mislabeled sensitive answers cannot disable review');
insert into public.answer_library(question_key,question_pattern,answer_text,category,requires_review,verified_by_candidate) values('sponsor','Do you need visa sponsorship?','Synthetic response','routine',true,true);
select ok((select requires_review from public.answer_library),'sensitive question overrides an incorrect routine label');
select lives_ok($$select public.record_application_package('55000000-0000-0000-0000-000000000001','35000000-0000-0000-0000-000000000001','65000000-0000-0000-0000-000000000001',(select updated_at from public.applications),(select updated_at from public.jobs),(select updated_at from public.candidate_profiles),(select updated_at from public.resume_facts),public.answer_version_snapshot(),'{"answers":[],"cover_letter":"Synthetic letter"}')$$,'verified source snapshot generates package');
select lives_ok($$select public.record_application_package('55000000-0000-0000-0000-000000000001','35000000-0000-0000-0000-000000000001','65000000-0000-0000-0000-000000000001',now(),now(),now(),now(),'[]','{}')$$,'same request retries resolve to the existing immutable package');
select is((select count(*) from public.application_packages),1::bigint,'idempotent retry does not duplicate a version');
select is((select count(*) from public.application_events where event_type='package_generated'),1::bigint,'one generation event per version');
select lives_ok($$select public.review_application_package((select id from public.application_packages),(select updated_at from public.applications))$$,'candidate can review a current fully answered package');
select is((select status from public.applications),'needs_review','unassessed eligibility still needs review');
select is((select applied_at from public.applications),null::timestamptz,'document preparation is not submission');
select is((select count(*) from public.package_reviews),1::bigint,'historical candidate review retained');
select throws_ok($$update public.application_packages set content='{}'$$,'42501',null,'Data API cannot rewrite version contents');
update public.answer_library set answer_text='Changed synthetic answer';
select throws_ok($$select public.review_application_package((select id from public.application_packages),(select updated_at from public.applications))$$,'40001',null,'answer changes invalidate package review');
select throws_ok($$select public.record_application_package('55000000-0000-0000-0000-000000000001','35000000-0000-0000-0000-000000000001','65000000-0000-0000-0000-000000000002',now(),now(),now(),now(),public.answer_version_snapshot(),'{}')$$,'40001',null,'stale source revisions are rejected');
select lives_ok($$select public.record_application_package('55000000-0000-0000-0000-000000000001','35000000-0000-0000-0000-000000000001','65000000-0000-0000-0000-000000000002',(select updated_at from public.applications),(select updated_at from public.jobs),(select updated_at from public.candidate_profiles),(select updated_at from public.resume_facts),public.answer_version_snapshot(),'{"answers":[{"answer":null}],"cover_letter":"Synthetic letter"}')$$,'unresolved questions can be previewed');
select throws_ok($$select public.review_application_package((select id from public.application_packages where request_id='65000000-0000-0000-0000-000000000002'),(select updated_at from public.applications))$$,'23514',null,'unanswered questions cannot be approved');
set local request.jwt.claim.sub='15000000-0000-0000-0000-000000000002';
select is((select count(*) from public.application_packages),0::bigint,'other owner cannot read private versions');
select is((select count(*) from public.resume_facts),0::bigint,'other owner cannot read candidate facts');
select is((select count(*) from public.package_reviews),0::bigint,'other owner cannot read review records');
select throws_ok($$select public.review_application_package('65000000-0000-0000-0000-000000000001',now())$$,'42501',null,'foreign or unknown package IDs denied');
reset role;
select lives_ok($$delete from auth.users where id='15000000-0000-0000-0000-000000000001'$$,'account cascade removes versions and facts without retaining private data');
select * from finish();
rollback;
